import * as React from "react";

function ownedTabs(list: HTMLElement) {
	return Array.from(
		list.querySelectorAll<HTMLElement>('[data-slot="tabs-trigger"]')
	).filter(
		(tab) =>
			tab.closest('[role="tablist"]') === list &&
			!tab.hasAttribute("disabled") &&
			!tab.hasAttribute("data-disabled") &&
			tab.getAttribute("aria-disabled") !== "true"
	);
}

function focusedElement(node: HTMLElement) {
	const root = node.getRootNode();
	return "activeElement" in root ? root.activeElement : null;
}

function focusFirst(candidates: HTMLElement[]) {
	const previouslyFocused = candidates[0]
		? focusedElement(candidates[0])
		: null;
	for (const candidate of candidates) {
		if (!candidate.isConnected) continue;
		if (candidate === previouslyFocused) return;
		candidate.focus();
		// document.activeElement remains the host when focus is inside a shadow.
		// A consumer onFocus may deliberately redirect focus; preserve that too.
		if (focusedElement(candidate) !== previouslyFocused) return;
	}
}

function focusTabsOnEntry(list: HTMLElement) {
	const tabs = ownedTabs(list);
	const selected = tabs.find(
		(tab) => tab.getAttribute("aria-selected") === "true"
	);
	const current = tabs.find((tab) => tab.tabIndex === 0);
	focusFirst(
		Array.from(new Set([selected, current, ...tabs])).filter(
			(tab): tab is HTMLElement => Boolean(tab)
		)
	);
}

function useTabsFocusTimer() {
	const pending = React.useRef<{ view: Window; id: number } | null>(null);
	React.useEffect(
		() => () => {
			if (pending.current)
				pending.current.view.clearTimeout(pending.current.id);
		},
		[]
	);
	return pending;
}

/** Keep Radix selection/roving state; repair only its owner-root focus lookup. */
function handleTabsArrowNavigation(
	event: React.KeyboardEvent<HTMLElement>,
	loop: boolean,
	pending: ReturnType<typeof useTabsFocusTimer>,
	onShiftTab: () => void
) {
	if (event.key === "Tab" && event.shiftKey) {
		onShiftTab?.();
		return;
	}
	if (
		event.target !== event.currentTarget ||
		event.altKey ||
		event.ctrlKey ||
		event.metaKey ||
		event.shiftKey
	)
		return;
	const source = event.currentTarget;
	const list = source.closest<HTMLElement>('[role="tablist"]');
	const view = source.ownerDocument.defaultView;
	if (!list || !view) return;
	const vertical = list.getAttribute("aria-orientation") === "vertical";
	const rtl = view.getComputedStyle(list).direction === "rtl";
	let intent: "first" | "last" | "previous" | "next";
	if (event.key === "Home" || event.key === "PageUp") intent = "first";
	else if (event.key === "End" || event.key === "PageDown") intent = "last";
	else if (vertical && event.key === "ArrowUp") intent = "previous";
	else if (vertical && event.key === "ArrowDown") intent = "next";
	else if (!vertical && event.key === "ArrowLeft")
		intent = rtl ? "next" : "previous";
	else if (!vertical && event.key === "ArrowRight")
		intent = rtl ? "previous" : "next";
	else return;

	event.preventDefault();
	if (!ownedTabs(list).includes(source)) return;
	if (pending.current) pending.current.view.clearTimeout(pending.current.id);
	// Like Radix, defer arrow focus until React finishes the key event batch.
	const id = view.setTimeout(() => {
		pending.current = null;
		if (
			!list.isConnected ||
			!source.isConnected ||
			focusedElement(source) !== source
		)
			return;
		let candidates = ownedTabs(list);
		if (!candidates.includes(source)) return;
		if (intent === "last" || intent === "previous") candidates.reverse();
		if (intent === "previous" || intent === "next") {
			const index = candidates.indexOf(source);
			if (index < 0) return;
			candidates = loop
				? [
						...candidates.slice(index + 1),
						...candidates.slice(0, index + 1),
					]
				: candidates.slice(index + 1);
		}
		focusFirst(candidates);
	}, 0);
	pending.current = { view, id };
}

export { focusTabsOnEntry, handleTabsArrowNavigation, useTabsFocusTimer };

"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { Tabs as TabsPrimitive } from "radix-ui";

import { cn } from "@/lib/utils";
import { wrapHugText } from "@/components/ui/hug-text";
import {
	focusTabsOnEntry,
	handleTabsArrowNavigation,
	useTabsFocusTimer,
} from "@/components/ui/tabs.keyboard";

const TabsKeyboardContext = React.createContext<{
	loop: boolean;
	pending: ReturnType<typeof useTabsFocusTimer>;
	onShiftTab: () => void;
} | null>(null);

function Tabs({
	className,
	orientation = "horizontal",
	...props
}: React.ComponentProps<typeof TabsPrimitive.Root>) {
	return (
		<TabsPrimitive.Root
			orientation={orientation}
			data-slot="tabs"
			data-orientation={orientation}
			className={cn(
				"group/tabs flex gap-2 data-horizontal:flex-col",
				className
			)}
			{...props}
		/>
	);
}

const tabsListVariants = cva(
	"group/tabs-list inline-flex w-fit items-center gap-1 rounded-full bg-snapp-surface-primary p-2 font-sans text-sm leading-5 font-normal text-snapp-text-brand group-data-vertical/tabs:flex-col data-[variant=line]:rounded-none",
	{
		variants: {
			variant: {
				default: "bg-snapp-surface-primary",
				line: "h-12 gap-4 rounded-none border-b border-snapp-border-primary bg-snapp-surface-primary p-0",
			},
		},
		defaultVariants: {
			variant: "default",
		},
	}
);

function TabsList({
	appearance = "default",
	className,
	variant = "default",
	loop = true,
	onMouseDown,
	onFocus,
	onBlur,
	...props
}: React.ComponentProps<typeof TabsPrimitive.List> &
	VariantProps<typeof tabsListVariants> & {
		appearance?: "default" | "header";
	}) {
	const clickFocus = React.useRef(false);
	const tabbingBackOut = React.useRef(false);
	const pending = useTabsFocusTimer();
	const keyboard = React.useMemo(
		() => ({
			loop,
			pending,
			onShiftTab: () => {
				tabbingBackOut.current = true;
			},
		}),
		[loop, pending]
	);
	return (
		<TabsKeyboardContext.Provider value={keyboard}>
			<TabsPrimitive.List
				loop={loop}
				data-slot="tabs-list"
				data-variant={variant}
				className={cn(
					tabsListVariants({ variant }),
					appearance === "header" && "border-0",
					className
				)}
				{...props}
				onMouseDown={(event) => {
					onMouseDown?.(event);
					if (!event.defaultPrevented) clickFocus.current = true;
				}}
				onFocus={(event) => {
					onFocus?.(event);
					if (event.defaultPrevented) return;
					const list = event.currentTarget;
					if (
						event.target === list &&
						!clickFocus.current &&
						!tabbingBackOut.current &&
						"host" in list.getRootNode()
					) {
						event.preventDefault();
						focusTabsOnEntry(list);
					}
					clickFocus.current = false;
				}}
				onBlur={(event) => {
					onBlur?.(event);
					if (!event.defaultPrevented) tabbingBackOut.current = false;
				}}
			/>
		</TabsKeyboardContext.Provider>
	);
}

function TabsTrigger({
	appearance = "default",
	className,
	children,
	onKeyDown,
	...props
}: React.ComponentProps<typeof TabsPrimitive.Trigger> & {
	appearance?: "default" | "header" | "header-emphasis";
}) {
	const keyboard = React.useContext(TabsKeyboardContext);
	return (
		<TabsPrimitive.Trigger
			data-slot="tabs-trigger"
			className={cn(
				"relative inline-flex h-9 shrink-0 items-center justify-center gap-2 rounded-full border-0 px-4 py-2 font-sans text-sm leading-5 font-normal whitespace-nowrap text-snapp-text-brand outline-none transition-colors group-data-vertical/tabs:w-full group-data-vertical/tabs:justify-start hover:bg-snapp-surface-secondary focus-visible:ring-2 focus-visible:ring-snapp-border-highlight focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-5",
				"group-data-[variant=default]/tabs-list:data-[state=active]:bg-snapp-surface-brand group-data-[variant=default]/tabs-list:data-[state=active]:text-snapp-text-invert",
				"group-data-[variant=line]/tabs-list:h-full group-data-[variant=line]/tabs-list:rounded-none group-data-[variant=line]/tabs-list:px-0 group-data-[variant=line]/tabs-list:py-0 group-data-[variant=line]/tabs-list:text-snapp-text-soft group-data-[variant=line]/tabs-list:hover:bg-transparent group-data-[variant=line]/tabs-list:data-[state=active]:font-bold group-data-[variant=line]/tabs-list:data-[state=active]:text-snapp-text-brand",
				"after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-snapp-border-highlight after:opacity-0 group-data-[variant=line]/tabs-list:data-[state=active]:after:opacity-100 group-data-vertical/tabs:after:inset-y-0 group-data-vertical/tabs:after:right-0 group-data-vertical/tabs:after:left-auto group-data-vertical/tabs:after:h-auto group-data-vertical/tabs:after:w-0.5",
				appearance === "header" && "gap-2",
				appearance === "header-emphasis" &&
					"gap-2 group-data-[variant=line]/tabs-list:text-snapp-text-brand",
				className
			)}
			{...props}
			onKeyDown={(event) => {
				onKeyDown?.(event);
				if (!event.defaultPrevented && keyboard) {
					handleTabsArrowNavigation(
						event,
						keyboard.loop,
						keyboard.pending,
						keyboard.onShiftTab
					);
				}
			}}
		>
			{props.asChild ? children : wrapHugText(children)}
		</TabsPrimitive.Trigger>
	);
}

function TabsContent({
	className,
	...props
}: React.ComponentProps<typeof TabsPrimitive.Content>) {
	return (
		<TabsPrimitive.Content
			data-slot="tabs-content"
			className={cn("flex-1 text-sm outline-none", className)}
			{...props}
		/>
	);
}

export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants };
